#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from pathlib import Path

DATA_URI = 'data:image/webp;base64,'


def main():
    js_path = Path('ranking-season-ui.js')
    js = js_path.read_text(encoding='utf-8')
    old = 'assets/q-icons/wcs2026icon.webp?v=2026'
    if old not in js:
        raise RuntimeError('找不到目前 WCS 圖示來源，停止修改')
    js = js.replace(old, DATA_URI, 1)
    js_path.write_text(js, encoding='utf-8')

    index_path = Path('index.html')
    index = index_path.read_text(encoding='utf-8')
    index = index.replace('ranking-season-ui.js?v=2.1.0-r2', 'ranking-season-ui.js?v=2.1.0-r3')
    index_path.write_text(index, encoding='utf-8')


if __name__ == '__main__':
    main()
